from random import choice
import numpy as np
import pandas as pd

# Constants
TEAMS = ['Team A', 'Team B', 'Team C', 'Team D', 'Team E']
PENALTIES_COSTS = [100, 200, 300, 400, 500]

def task_func(goals, penalties, teams=TEAMS, penalties_costs=PENALTIES_COSTS):
    goals = list(goals)
    penalties = list(penalties)
    teams = list(teams)
    penalties_costs = list(penalties_costs)

    if not penalties_costs:
        raise ValueError("penalties_costs must not be empty.")

    if len(goals) != len(penalties) or len(goals) != len(teams):
        raise ValueError("goals, penalties, and teams must have the same length.")

    if len(teams) == 0:
        return pd.DataFrame(
            columns=['Team', 'Goals', 'Penalties', 'Penalties Cost', 'Performance Score']
        )

    rows = []
    for team, goal, penalty in zip(teams, goals, penalties):
        rows.append(
            {
                'Team': team,
                'Goals': goal,
                'Penalties': penalty,
                'Penalties Cost': choice(penalties_costs),
                'Performance Score': max(goal - penalty, 0),
            }
        )

    return pd.DataFrame(
        rows,
        columns=['Team', 'Goals', 'Penalties', 'Penalties Cost', 'Performance Score'],
    )
